commands.command:
set -eu; STOCK_PW=$(cat /root/.stock_app_password); AUDITOR_PW=$(cat /root/.auditor_password); sudo -u postgres psql -v ON_ERROR_STOP=1 -c "CREATE ROLE stock_app LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION PASSWORD '$STOCK_PW'"; sudo -u postgres psql -v ON_ERROR_STOP=1 -c "CREATE ROLE auditor LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION PASSWORD '$AUDITOR_PW'"; sudo -u postgres createdb -O postgres branch_stock; sudo -u postgres psql -v ON_ERROR_STOP=1 -d branch_stock -f /srv/legacy2/database-reader-writer-roles/stock.sql; sudo -u postgres psql -v ON_ERROR_STOP=1 -d branch_stock <<'SQL'
REVOKE ALL ON DATABASE branch_stock FROM PUBLIC;
GRANT CONNECT ON DATABASE branch_stock TO stock_app, auditor;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO stock_app, auditor;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
GRANT SELECT ON TABLE stock TO stock_app;
GRANT UPDATE (quantity) ON TABLE stock TO stock_app;
GRANT SELECT ON TABLE stock, supplier_costs TO auditor;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON TABLES FROM PUBLIC;
SQL
rm -f /root/.stock_app_password /root/.auditor_password; echo database_roles_schema_and_grants_created
